for (size_t i = start; i < end; i++) {
    Particle &pi = particles[i];
    pi.density = 0.0f;
    pi.force = {0.0f, 0.0f, 0.0f};

    // Calculate density using kernel summation
    for (int nx = -1; nx <= 1; nx++) {
        for (int ny = -1; ny <= 1; ny++) {
            for (int nz = -1; nz <= 1; nz++) {
                int32_t key = hash_key(pi.hash_base, nx, ny, nz);
                uint32_t index = particleTable[key];
                while (index != 0xFFFFFFFF) {
                    Particle &pj = particles[index];
                    float dx = pj.position.x - pi.position.x;
                    float dy = pj.position.y - pi.position.y;
                    float dz = pj.position.z - pi.position.z;
                    float r = std::sqrt(dx*dx + dy*dy + dz*dz);

                    if (r < h && r > 0.0f) {
                        // Calculate density contribution
                        float ratio = r/h;
                        float weight = 1.0f - ratio;
                        pi.density += mass * weight * weight * weight;

                        // Calculate pressure force
                        float poly6 = (h2 - r*r) * (h2 - r*r) * (h2 - r*r);
                        float spiky = (h - r) * (h - r);
                        float WspikyGrad = spikyGrad * (h - r) * (h - r);

                        // Pressure force
                        float pressure_term = -mass * (pi.pressure + pj.pressure) / (2.0f * pj.density);
                        pi.force.x += pressure_term * (-dx/r) * WspikyGrad;
                        pi.force.y += pressure_term * (-dy/r) * WspikyGrad;
                        pi.force.z += pressure_term * (-dz/r) * WspikyGrad;

                        // Viscosity force
                        float WspikyLap = spikyLap * (h - r);
                        pi.force.x += viscosity * mass * (pj.velocity.x - pi.velocity.x) * WspikyLap;
                        pi.force.y += viscosity * mass * (pj.velocity.y - pi.velocity.y) * WspikyLap;
                        pi.force.z += viscosity * mass * (pj.velocity.z - pi.velocity.z) * WspikyLap;
                    }
                    index = pj.next;
                }
            }
        }
    }

    // Apply forces to acceleration
    pi.force.x /= pi.density;
    pi.force.y /= pi.density;
    pi.force.z /= pi.density;
    pi.acceleration.x = pi.force.x;
    pi.acceleration.y = pi.force.y;
    pi.acceleration.z = pi.force.z;
}
